<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {importApi} from '../api/imports'
import {useCustomers} from '../composables/useCustomers'
import {errorText} from '../api/client'
import {dateTime} from '../utils/format'
import type {TaskSummary} from '../types/api'
import PageHeading from '../components/PageHeading.vue'
import StatusBadge from '../components/StatusBadge.vue'
const router=useRouter(),route=useRoute(),{customers,customerError}=useCustomers(),tasks=ref<TaskSummary[]>([]),loading=ref(false),error=ref(''),total=ref(0),page=ref(1),size=ref(20)
const customer=ref(''),filename=ref(''),status=ref(''),dates=ref<string[]>([])
let sequence=0
async function load(){const token=++sequence;loading.value=true;error.value='';try{const result=await importApi.tasks({page:page.value,page_size:size.value,customer_id:customer.value||undefined,file_name:filename.value||undefined,status:status.value||undefined,date_from:dates.value?.[0],date_to:dates.value?.[1]});if(token===sequence){tasks.value=result.items;total.value=result.total}}catch(e){if(token===sequence)error.value=errorText(e)}finally{if(token===sequence)loading.value=false}}
function search(){page.value=1;router.replace({path:'/tasks',query:{...(customer.value?{customer:customer.value}:{}),...(filename.value?{file:filename.value}:{}),...(status.value?{status:status.value}:{}),...(dates.value?.[0]?{from:dates.value[0],to:dates.value[1]}:{})}});load()}
function reset(){customer.value='';filename.value='';status.value='';dates.value=[];search()}
onMounted(()=>{customer.value=String(route.query.customer||'');filename.value=String(route.query.file||'');status.value=String(route.query.status||'');dates.value=route.query.from&&route.query.to?[String(route.query.from),String(route.query.to)]:[];load()})
</script>
<template><PageHeading title="历史导入任务" eyebrow="IMPORT HISTORY" subtitle="直接浏览数据库中的完整历史任务，按客户、文件、日期和状态查询，无需输入任务编号。"><el-button :disabled="loading" @click="load">刷新列表</el-button><el-button type="primary" @click="router.push('/import')">批量导入</el-button></PageHeading>
<form class="query-bar task-filters" @submit.prevent="search"><el-select v-model="customer" clearable placeholder="全部客户" aria-label="筛选任务客户"><el-option v-for="c in customers" :key="c.customer_id" :value="c.customer_id" :label="c.customer_name+'（'+c.customer_id+'）'"/></el-select><el-input v-model="filename" clearable placeholder="按文件名搜索" aria-label="文件名筛选"/><el-select v-model="status" clearable placeholder="全部状态" aria-label="筛选任务状态"><el-option label="处理中" value="PROCESSING"/><el-option label="处理完成" value="SUCCESS"/><el-option label="部分成功" value="PARTIAL_SUCCESS"/><el-option label="未建单（含待处理与文件异常）" value="FAILED"/></el-select><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="上传开始日期" end-placeholder="上传结束日期"/><el-button @click="reset">重置</el-button><el-button type="primary" native-type="submit" :disabled="loading">查询</el-button></form>
<el-alert v-if="customerError||error" :title="customerError||error" type="error" :closable="false" class="section-alert"/>
<section class="panel table-panel" v-loading="loading"><div class="panel-heading"><h2>历史任务 <span class="count-pill">{{total}}</span></h2><span class="muted">最近上传优先</span></div><el-table :data="tasks" row-key="task_id" max-height="620"><el-table-column prop="task_id" label="任务编号" width="100"/><el-table-column prop="customer_id" label="客户" width="110"/><el-table-column prop="file_name" label="文件名称" min-width="230" show-overflow-tooltip/><el-table-column label="上传时间" min-width="175"><template #default="{row}">{{dateTime(row.created_at||row.started_at)}}</template></el-table-column><el-table-column label="处理结果" width="220"><template #default="{row}"><StatusBadge :status="row.status" :description="row.status_description"/></template></el-table-column><el-table-column label="处理统计" min-width="230"><template #default="{row}">新建 {{row.success_rows}} / 未匹配 {{row.unmatched_rows}} / 失败 {{row.failed_rows}}<br/>重复 {{row.duplicate_rows||0}} / 待核实 {{row.review_rows||0}}</template></el-table-column><el-table-column label="配置版本" width="100"><template #default="{row}">V{{row.config_version??'—'}}</template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push('/tasks/'+row.task_id)">查看详情</el-button><el-button v-if="row.error_message&&row.total_rows===0&&row.status==='FAILED'" link @click="router.push({path:'/import',query:{retry_of:row.task_id}})">重新上传</el-button></template></el-table-column></el-table><div class="table-footer"><span>共 {{total}} 个任务</span><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50,100]" layout="sizes,prev,pager,next" :disabled="loading" @current-change="load" @size-change="page=1;load()"/></div></section>
</template>
<style scoped>.task-filters{flex-wrap:wrap;gap:12px}.task-filters .el-select{width:180px}.task-filters .el-input{width:220px}</style>
